TEST(ClassyMcClassfaceTest, BsonEmptyIsDefault)
{
    testspace::ClassyMcClassface in, out;
    in.Set_a_mydouble100(3.14159);
    in.Set_b_myuint32_200(3000000000);
    in.Set_c_myint64_201(-9000000000);
    in.Set_d_myfloat202(3.5);
    in.Set_e_myint16_203(-12345);
    in.Set_f_myuint16_204(60000);
    in.Set_g_myint32_205(-2000000000);
    in.Set_h_myuint64_206(12000000000);
    in.Set_i_charcoal301(65);
    in.Set_j_mystring302("skywire");
    in.Set_k_uchar303(200);
    in.Set_l_myuint8_304(201);
    in.Set_m_myint8_305(-50);
    in.Set_n_shortstring306("skywire");
    in.Set_o_myfloat1000(3.5);
    in.Set_p_myuint32_2000(3000000000);
    in.Set_q_myint64_2010(-9000000000);
    in.Set_r_mydouble2020(3.14159);

    out = in;
    ASSERT_TRUE(out.from_bson(std::string("\x05\0\0\0\0", 5)));
    ASSERT_EQ(testspace::ClassyMcClassface(), out);
}

TEST(ClassyMcClassfaceTest, BsonLargeUint64_h_myuint64_206)
{
    testspace::ClassyMcClassface in, out;
    static const uint8_t big[] = {
        0x13, 0x68, 0x5f, 0x6d, 0x79, 0x75, 0x69, 0x6e,
        0x74, 0x36, 0x34, 0x5f, 0x32, 0x30, 0x36, 0x00,
        0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff,
        0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x40, 0x30,
    };
    static const uint8_t edge[] = {
        0x12, 0x68, 0x5f, 0x6d, 0x79, 0x75, 0x69, 0x6e,
        0x74, 0x36, 0x34, 0x5f, 0x32, 0x30, 0x36, 0x00,
        0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0x7f,
    };
    in.Set_h_myuint64_206(UINT64_C(18446744073709551615));
    std::string bytes = in.to_bson();
    ASSERT_NE(std::string::npos, bytes.find(std::string(reinterpret_cast<const char*>(big), sizeof(big))));
    ASSERT_TRUE(out.from_bson(bytes));
    ASSERT_EQ(in, out);
    in.Set_h_myuint64_206(UINT64_C(9223372036854775807));
    bytes = in.to_bson();
    ASSERT_NE(std::string::npos, bytes.find(std::string(reinterpret_cast<const char*>(edge), sizeof(edge))));
    ASSERT_TRUE(out.from_bson(bytes));
    ASSERT_EQ(in, out);
}

